use gpui::{div, px, IntoElement, ParentElement, Styled};

pub struct Usage {
    pub label: String,
    pub used: f32,
}

pub fn usage_row(usage: &Usage) -> impl IntoElement {
    let filled = px(160.0 * usage.used.clamp(0.0, 1.0));
    div()
        .flex()
        .gap(px(8.0))
        .child(div().w(px(96.0)).child(usage.label.clone()))
        .child(div().w(px(160.0)).h(px(6.0)).rounded(px(3.0)).bg(gpui::rgb(0x2a2a33)).child(div().w(filled).h(px(6.0)).rounded(px(3.0)).bg(gpui::rgb(0x61ffca))))
}

